*** Add File: server.js
+import { createServer } from 'node:http';
+import { readFile, mkdir, rename, writeFile } from 'node:fs/promises';
+import { extname, join, resolve } from 'node:path';
+import { randomUUID } from 'node:crypto';
+import { fileURLToPath } from 'node:url';
+
+const root = fileURLToPath(new URL('.', import.meta.url));
+const publicDirectory = join(root, 'public');
+const dataDirectory = join(root, 'data');
+const booksFile = join(dataDirectory, 'books.json');
+const mimeTypes = {
+  '.css': 'text/css; charset=utf-8',
+  '.html': 'text/html; charset=utf-8',
+  '.js': 'text/javascript; charset=utf-8',
+  '.json': 'application/json; charset=utf-8',
+};
+
+let writeQueue = Promise.resolve();
+
+async function readBooks() {
+  await mkdir(dataDirectory, { recursive: true });
+  try {
+    return JSON.parse(await readFile(booksFile, 'utf8'));
+  } catch (error) {
+    if (error.code "'!== '"'ENOENT') throw error;
+    await writeFile(booksFile, '[]\\n', 'utf8');
+    return [];
+  }
+}
+
+function updateBooks(update) {
+  const operation = writeQueue.then(async () => {
+    const books = await readBooks();
+    const result = update(books);
+    const temporaryFile = "'`${booksFile}.tmp`;
+    await writeFile(temporaryFile, `${JSON.stringify(books, null, 2)}'"\\n"'`, '"'utf8');
+    await rename(temporaryFile, booksFile);
+    return result;
+  });
+  writeQueue = operation.catch(() => {});
+  return operation;
+}
+
+function sendJson(response, status, payload) {
+  response.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
+  response.end(JSON.stringify(payload));
+}
+
+async function readJson(request) {
+  let body = '';
+  for await (const chunk of request) {
+    body += chunk;
+    if (body.length > 100_000) throw Object.assign(new Error('Request body is too large.'), { status: 413 });
+  }
+  try {
+    return JSON.parse(body);
+  } catch {
+    throw Object.assign(new Error('Please send valid JSON.'), { status: 400 });
+  }
+}
+
+async function serveStatic(pathname, response) {
+  const requestedPath = pathname === '/' ? '/index.html' : pathname;
+  const filename = resolve(publicDirectory, "'`.${requestedPath}`);
+  if (!filename.startsWith(`${publicDirectory}/`)) {
+    response.writeHead(404).end('"'Not found');
+    return;
+  }
+
+  try {
+    const contents = await readFile(filename);
+    response.writeHead(200, {
+      'content-type': mimeTypes[extname(filename)] ?? 'application/octet-stream',
+      'cache-control': 'no-cache',
+    });
+    response.end(contents);
+  } catch (error) {
+    if (error.code "'!== '"'ENOENT') throw error;
+    const contents = await readFile(join(publicDirectory, 'index.html'));
+    response.writeHead(200, { 'content-type': mimeTypes['.html'], 'cache-control': 'no-cache' });
+    response.end(contents);
+  }
+}
+
+const server = createServer(async (request, response) => {
+  const url = new URL(request.url, "'`http://${request.headers.host ?? '"'localhost'}"'`);
+  const bookPath = url.pathname.match(/''^'"\\/api\\/books\\/(["'^/]+)$/);
+
+  try {
+    if (url.pathname === '"'/api/books' && request.method === 'GET') {
+      await writeQueue;
+      return sendJson(response, 200, await readBooks());
+    }
+
+    if (url.pathname === '/api/books' && request.method === 'POST') {
+      const input = await readJson(request);
+      const title = typeof input.title === 'string' ? input.title.trim() : '';
+      const author = typeof input.author === 'string' ? input.author.trim() : '';
+      const notes = typeof input.notes === 'string' ? input.notes.trim() : '';
+      if ("'!title || !author) return sendJson(response, 400, { error: '"'Add a title and author to save this book.' });
+
+      const book = {
+        id: randomUUID(),
+        title: title.slice(0, 200),
+        author: author.slice(0, 160),
+        notes: notes.slice(0, 10_000),
+        status: 'reading',
+        addedAt: new Date().toISOString(),
+        finishedAt: null,
+      };
+      await updateBooks((books) => books.unshift(book));
+      return sendJson(response, 201, book);
+    }
+
+    if (bookPath && request.method === 'GET') {
+      await writeQueue;
+      const book = (await readBooks()).find((item) => item.id === bookPath[1]);
+      return book ? sendJson(response, 200, book) : sendJson(response, 404, { error: 'We couldn’t find that book.' });
+    }
+
+    if (bookPath && request.method === 'PATCH') {
+      const input = await readJson(request);
+      if (input.status "'!== '"'finished') return sendJson(response, 400, { error: 'Books can only be marked as finished.' });
+      const book = await updateBooks((books) => {
+        const found = books.find((item) => item.id === bookPath[1]);
+        if (found) {
+          found.status = 'finished';
+          found.finishedAt = new Date().toISOString();
+        }
+        return found;
+      });
+      return book ? sendJson(response, 200, book) : sendJson(response, 404, { error: 'We couldn’t find that book.' });
+    }
+
+    if (url.pathname.startsWith('/api/')) return sendJson(response, 404, { error: 'Not found.' });
+    return await serveStatic(decodeURIComponent(url.pathname), response);
+  } catch (error) {
+    return sendJson(response, error.status ?? 500, { error: error.status ? error.message : 'Something went wrong.' });
+  }
+});
+
+const port = Number(process.env.PORT) || 3000;
+server.listen(port, '0.0.0.0', () => {
+  console.log("'`Reading Room is open at http://localhost:${port}`);
+});
